#!/usr/bin/env python3
# coding: utf-8

""" Golden-value parity for the numba metric kernels (captured from the former
Cython metrics_cy before removal).

roll_annual_volatility is the exception: the Cython aliased its return buffer
with the output (``cdef double[:] R = var``), corrupting the rolling sums into
NaN for t > w. The numba port fixes this (separate R array); we assert parity
on the valid prefix [0, w] and correctness (no NaN, clean rolling std) after. """

import numpy as np

from fynance.features._metrics_helpers import (
    _drawdown_1d,
    _drawdown_2d,
    _roll_annual_return_1d,
    _roll_annual_return_2d,
    _roll_annual_volatility_1d,
    _roll_drawdown_1d,
    _roll_mad_1d,
    _roll_mad_2d,
    _roll_mdd_1d,
    _roll_mdd_2d,
)

_RNG = np.random.default_rng(13)
X1 = (100 * np.cumprod(1 + _RNG.normal(0.001, 0.02, 40))).astype(np.float64)
X2 = (100 * np.cumprod(1 + _RNG.normal(0.001, 0.02, (40, 3)), axis=0)).astype(np.float64)


