def test_roll_annual_volatility_prefix_parity_and_fix():
    # parity with Cython on the valid prefix [0, w] (w=5)
    gold_prefix = [0.0, 0.480732787305, 0.54458255891, 0.48406059897, 0.492196226584, 0.497180037393]
    mine = _roll_annual_volatility_1d(X1, 252, 0, 5, 0)
    assert np.allclose(mine[:6], gold_prefix, atol=1e-9)
    # fix: no NaN (the Cython produced NaN for t > w via buffer aliasing)
    assert not np.isnan(mine).any()
    # correctness: matches a clean numpy rolling-variance reference
    R = np.zeros(40)
    R[1:] = X1[1:] / X1[:-1] - 1.0
    ref = np.zeros(40)
    for t in range(1, 40):
        if t < 5:
            win = R[0:t + 1]
            _w = t + 1
            _wd = t + 1
        else:
            win = R[t - 4:t + 1]
            _w = 5
            _wd = 5
        S = win.sum()
        S2 = (win * win).sum()
        ref[t] = np.sqrt(252 * (S2 - (S / _w) * S) / _wd)
    assert np.allclose(mine, ref, atol=1e-9)
